public class FastMath_max_TriageGen3Test {

    private static final float DELTA = 1e-7f;





    @Test
    public void testMax_aGreaterThanB_NotNaN() {
        // Covers (a <= b) is false, and (Float.isNaN(a + b)) is false
        // Note: The logic in the provided method: (a <= b) ? b : (Float.isNaN(a + b) ? Float.NaN : b)
        // If a > b, it checks if a + b is NaN. If not NaN, it returns b.
        // This is a very unusual implementation of max, but we test the logic provided.
        float a = 10.0f;
        float b = 2.0f;
        assertEquals(b, FastMath.max(a, b), DELTA);
    }






}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FastMath_max_TriageGen3Test {

    private static final float DELTA = 1e-7f;







    @Test
    public void testMax_aGreaterThanB_IsNaN() {
        // Covers (a <= b) is false, and (Float.isNaN(a + b)) is true
        // To make a + b NaN, one must be NaN. 
        // However, if a is NaN, (a <= b) is false.
        float a = Float.NaN;
        float b = 1.0f;
        // (NaN <= 1.0f) is false.
        // Float.isNaN(NaN + 1.0f) is true.
        // Returns Float.NaN
        assertEquals(Float.NaN, FastMath.max(a, b), Float.NaN);
    }




}

