package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FastMath_max_TriageGen3Test {

    private static final float DELTA = 1e-7f;











    @Test
    public void testMax_Infinity() {
        float a = Float.POSITIVE_INFINITY;
        float b = 1.0f;
        // (Inf <= 1.0) is false.
        // (Inf + 1.0) is Inf, not NaN.
        // Returns b (1.0f) based on the provided code logic.
        assertEquals(b, FastMath.max(a, b), DELTA);

        float c = Float.NEGATIVE_INFINITY;
        float d = -10.0f;
        // (-Inf <= -10.0) is true.
        // Returns b (-10.0f).
        assertEquals(d, FastMath.max(c, d), DELTA);
    }
}
